Method.Source:
/// <summary>
/// Handles the canceled event for the workflow document.
/// </summary>
/// <param name="_workflowEventArgs">
/// An instance of the <c>WorkflowEventArgs</c> class.
/// </param>
public void canceled(WorkflowEventArgs _workflowEventArgs)
{        
    if (this.validateWorkflowContext(_workflowEventArgs))
    {
        FMVehicleMaintenance::setWorkflowStatus(
            _workflowEventArgs.parmWorkflowContext().parmRecId(),
            FMStatus::Done);
    }
}

/// <summary>
/// Validates a workflow context.
/// </summary>
/// <returns>
/// true if the workflow context is valid; otherwise, false.
/// </returns>
/// <remarks>
/// This method throws an exception if the workflow context is invalid.
/// </remarks>
private boolean validateWorkflowContext(WorkflowEventArgs _workflowEventArgs)
{
    WorkflowContext _context = _workflowEventArgs.parmWorkflowContext();

    //  contextTableId must not be zero.
    Debug::assert(_context.parmTableId() != 0);

    //  contextRecId must not be zero.
    Debug::assert(_context.parmRecId() != 0);

    if (_context.parmTableId() == 0)
    {
        throw error("@GLS190318");
    }

    if (_context.parmRecId() == 0)
    {
        throw error("@SYS107964");
    }


    return true;
}
